using FamilyVeda.Application.Common;
using FamilyVeda.Application.Portal;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Portal;
using FamilyVeda.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace FamilyVeda.Infrastructure.Portal;

public sealed class PortalNotificationService(AppDbContext dbContext, ICurrentUser currentUser) : IPortalNotificationService
{
    public async Task<IReadOnlyList<PortalNotificationDto>> GetMineAsync(bool unreadOnly, CancellationToken cancellationToken)
    {
        var query = dbContext.PortalNotifications.AsNoTracking().Where(x => x.UserId == currentUser.UserId);
        if (unreadOnly) query = query.Where(x => x.ReadAt == null);
        return await query.OrderByDescending(x => x.CreatedAt).Take(50)
            .Select(x => new PortalNotificationDto(x.Id, x.Type, x.Title, x.Body, x.LinkPath, x.ReadAt, x.CreatedAt))
            .ToListAsync(cancellationToken);
    }

    public async Task MarkReadAsync(Guid id, CancellationToken cancellationToken)
    {
        var notification = await dbContext.PortalNotifications.SingleOrDefaultAsync(x => x.Id == id && x.UserId == currentUser.UserId, cancellationToken)
            ?? throw new NotFoundException();
        notification.ReadAt ??= DateTimeOffset.UtcNow;
        await dbContext.SaveChangesAsync(cancellationToken);
    }
}

public sealed class PortalDashboardService(AppDbContext dbContext, ICurrentUser currentUser) : IPortalDashboardService
{
    private static readonly TriageStatus[] ClosedStatuses =
        [TriageStatus.Approved, TriageStatus.ApprovedRevised, TriageStatus.Rejected, TriageStatus.Escalated, TriageStatus.FailedSafe];

    public async Task<FamilyDashboardDto> GetFamilyDashboardAsync(CancellationToken cancellationToken)
    {
        var family = await dbContext.Families.AsNoTracking().Include(x => x.Members)
            .FirstOrDefaultAsync(x => x.CreatedByUserId == currentUser.UserId || x.Members.Any(m => m.UserId == currentUser.UserId), cancellationToken)
            ?? throw new NotFoundException();
        var isHead = family.CreatedByUserId == currentUser.UserId;
        var adultCutoff = DateOnly.FromDateTime(DateTime.UtcNow).AddYears(-18);
        var minorCount = family.Members.Count(x => x.DateOfBirth > adultCutoff);

        var relevantMemberIds = isHead
            ? family.Members.Where(x => x.UserId == currentUser.UserId || x.DateOfBirth > adultCutoff).Select(x => x.Id).ToList()
            : family.Members.Where(x => x.UserId == currentUser.UserId).Select(x => x.Id).ToList();

        var nextAppointmentEntity = await dbContext.Appointments.AsNoTracking()
            .Where(x => relevantMemberIds.Contains(x.MemberId) && x.StartsAt > DateTimeOffset.UtcNow &&
                        (x.Status == AppointmentStatus.Requested || x.Status == AppointmentStatus.Confirmed))
            .OrderBy(x => x.StartsAt)
            .FirstOrDefaultAsync(cancellationToken);
        AppointmentDto? nextAppointment = null;
        if (nextAppointmentEntity is not null)
        {
            var member = family.Members.Single(x => x.Id == nextAppointmentEntity.MemberId);
            var doctor = await dbContext.Doctors.AsNoTracking().Include(x => x.User).SingleAsync(x => x.Id == nextAppointmentEntity.DoctorId, cancellationToken);
            var doctorDto = new DoctorSummaryDto(doctor.Id, doctor.User?.DisplayName ?? "Unknown", doctor.Specialty, doctor.HospitalClinic, doctor.District, doctor.City, doctor.Languages);
            nextAppointment = new AppointmentDto(nextAppointmentEntity.Id, member.Id, member.DisplayName, family.Name, doctorDto,
                nextAppointmentEntity.StartsAt, nextAppointmentEntity.DurationMinutes, nextAppointmentEntity.Reason, nextAppointmentEntity.Status,
                nextAppointmentEntity.DoctorNote, nextAppointmentEntity.CreatedAt);
        }

        var pendingJoinRequests = isHead
            ? await dbContext.FamilyJoinRequests.CountAsync(x => x.FamilyId == family.Id && x.Status == PortalRequestStatus.Pending, cancellationToken)
            : (int?)null;

        var assignment = await dbContext.FamilyDoctorAssignments.AsNoTracking().Include(x => x.Doctor).ThenInclude(x => x!.User)
            .FirstOrDefaultAsync(x => x.FamilyId == family.Id && x.IsPrimary && x.EndedAt == null, cancellationToken);
        var doctorSummary = assignment?.Doctor is null
            ? null
            : new DoctorSummaryDto(assignment.Doctor.Id, assignment.Doctor.User?.DisplayName ?? "Unknown", assignment.Doctor.Specialty,
                assignment.Doctor.HospitalClinic, assignment.Doctor.District, assignment.Doctor.City, assignment.Doctor.Languages);

        var unread = await dbContext.PortalNotifications.CountAsync(x => x.UserId == currentUser.UserId && x.ReadAt == null, cancellationToken);
        var openCases = await dbContext.TriageCases.CountAsync(x => relevantMemberIds.Contains(x.MemberId) && !ClosedStatuses.Contains(x.Status), cancellationToken);
        var ownMemberIds = family.Members.Where(x => x.UserId == currentUser.UserId).Select(x => x.Id).ToList();
        var approvedGuidance = await dbContext.TriageCases.CountAsync(x => ownMemberIds.Contains(x.MemberId) &&
            (x.Status == TriageStatus.Approved || x.Status == TriageStatus.ApprovedRevised), cancellationToken);
        var visibleAppointmentIds = await dbContext.Appointments.AsNoTracking()
            .Where(x => relevantMemberIds.Contains(x.MemberId))
            .Select(x => x.Id)
            .ToListAsync(cancellationToken);
        var activityEvents = await dbContext.AuditLogs.AsNoTracking()
            .Where(x =>
                (x.SubjectMemberId.HasValue && relevantMemberIds.Contains(x.SubjectMemberId.Value)
                    && (x.EventType == "CASE_STATUS_CHANGED" || x.EventType == "LAB_REPORT_MANUAL_REVIEW"))
                || (x.ResourceType == "Appointment" && x.ResourceId.HasValue
                    && visibleAppointmentIds.Contains(x.ResourceId.Value)
                    && (x.EventType == "APPOINTMENT_REQUESTED" || x.EventType == "APPOINTMENT_STATUS_CHANGED"))
                || (isHead && x.ActorUserId == currentUser.UserId && x.SubjectMemberId == null
                    && (x.EventType == "FAMILY_JOIN_ACCEPTED" || x.EventType == "FAMILY_JOIN_DECLINED"
                        || x.EventType == "FAMILY_DOCTOR_REQUESTED")))
            .OrderByDescending(x => x.CreatedAt)
            .Take(5)
            .Select(x => x.EventType)
            .ToListAsync(cancellationToken);
        var recentActivity = activityEvents.Select(eventType => eventType switch
        {
            "CASE_STATUS_CHANGED" => "Case updated",
            "LAB_REPORT_MANUAL_REVIEW" => "Lab report reviewed",
            "APPOINTMENT_REQUESTED" => "Appointment requested",
            "APPOINTMENT_STATUS_CHANGED" => "Appointment updated",
            "FAMILY_JOIN_ACCEPTED" => "Family join request accepted",
            "FAMILY_JOIN_DECLINED" => "Family join request declined",
            "FAMILY_DOCTOR_REQUESTED" => "Family doctor requested",
            _ => "Activity updated"
        }).ToList();

        return new FamilyDashboardDto(
            isHead ? "Head" : "AdultMember",
            family.Id,
            family.Name,
            isHead ? family.FamilyCode : null,
            family.Members.Count,
            minorCount,
            pendingJoinRequests,
            nextAppointment,
            openCases,
            approvedGuidance,
            doctorSummary,
            unread,
            recentActivity);
    }

    public async Task<DoctorDashboardDto> GetDoctorDashboardAsync(CancellationToken cancellationToken)
    {
        var doctor = await dbContext.Doctors.SingleOrDefaultAsync(x => x.UserId == currentUser.UserId, cancellationToken) ?? throw new NotFoundException();
        var today = new DateTimeOffset(DateTime.UtcNow.Date, TimeSpan.Zero);
        var tomorrow = today.AddDays(1);
        var todayAppointmentEntities = await dbContext.Appointments.AsNoTracking()
            .Where(x => x.DoctorId == doctor.Id && x.StartsAt >= today && x.StartsAt < tomorrow)
            .OrderBy(x => x.StartsAt)
            .ToListAsync(cancellationToken);
        var todayAppointments = new List<AppointmentDto>();
        foreach (var appointment in todayAppointmentEntities)
        {
            var member = await dbContext.Members.AsNoTracking().SingleAsync(x => x.Id == appointment.MemberId, cancellationToken);
            var family = await dbContext.Families.AsNoTracking().SingleAsync(x => x.Id == member.FamilyId, cancellationToken);
            var doctorDto = new DoctorSummaryDto(doctor.Id, doctor.User?.DisplayName ?? "Unknown", doctor.Specialty, doctor.HospitalClinic, doctor.District, doctor.City, doctor.Languages);
            todayAppointments.Add(new AppointmentDto(appointment.Id, member.Id, member.DisplayName, family.Name, doctorDto,
                appointment.StartsAt, appointment.DurationMinutes, appointment.Reason, appointment.Status, appointment.DoctorNote, appointment.CreatedAt));
        }

        // Clinical work is scoped by active, unexpired case grants — access by grant, not by role (RULE 8).
        var now = DateTimeOffset.UtcNow;
        var grantedCaseIds = dbContext.CaseAccessGrants
            .Where(x => x.DoctorId == doctor.Id && x.RevokedAt == null && x.ExpiresAt > now)
            .Select(x => x.TriageCaseId);
        var pendingApprovals = await dbContext.TriageCases.CountAsync(x => grantedCaseIds.Contains(x.Id) &&
            (x.Status == TriageStatus.PendingDoctorReview || x.Status == TriageStatus.LowConfidence || x.Status == TriageStatus.Claimed), cancellationToken);
        var openCases = await dbContext.TriageCases.CountAsync(x => grantedCaseIds.Contains(x.Id) && !ClosedStatuses.Contains(x.Status), cancellationToken);
        var pendingFamilyRequests = await dbContext.FamilyDoctorRequests.CountAsync(x => x.DoctorId == doctor.Id && x.Status == PortalRequestStatus.Pending, cancellationToken);
        var assignedFamilies = await dbContext.FamilyDoctorAssignments.CountAsync(x => x.DoctorId == doctor.Id && x.IsPrimary && x.EndedAt == null, cancellationToken);
        var unread = await dbContext.PortalNotifications.CountAsync(x => x.UserId == currentUser.UserId && x.ReadAt == null, cancellationToken);

        return new DoctorDashboardDto(todayAppointments, pendingApprovals, openCases, pendingFamilyRequests, assignedFamilies, unread);
    }
}
